using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Integration;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.CrossDomain;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Graph;using Microsoft.Extensions.DependencyInjection;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Catalog;
public sealed class AstronomyKnowledgeCatalogIntegrationTests{[Fact]public void Production_registration_exposes_representative_catalog_entries_and_existing_services(){var services=new ServiceCollection().AddAstronomyKnowledgeCatalog();using var p=services.BuildServiceProvider();var c=p.GetRequiredService<IAstronomyKnowledgeCatalog>();Assert.NotEmpty(c.Snapshot.Entries);Assert.Contains(c.Snapshot.Domains,e=>e.Code=="classification");Assert.Contains(c.Snapshot.PayloadFamilies,e=>e.Code=="entity-classification");Assert.Contains(c.Snapshot.KnowledgeTypes,e=>e.Code=="typed.classification.entity.v1");Assert.Contains(c.Snapshot.ValidationRules,e=>e.Code.Length>0);Assert.Contains(c.Snapshot.CrossDomainValidationRules,e=>e.Code.Length>0);Assert.Equal(11,c.Snapshot.GraphValidationRules.Count);Assert.Contains(c.Snapshot.StatementKinds,e=>e.Code=="scientific");Assert.True(c.TryGet(c.Snapshot.Entries[0].Id,out _));Assert.Same(c,p.GetRequiredService<IAstronomyKnowledgeCatalog>());Assert.NotNull(p.GetRequiredService<IAstronomyTypedPayloadRegistry>());Assert.NotNull(p.GetRequiredService<IAstronomyKnowledgeValidationRuleRegistry>());Assert.NotNull(p.GetRequiredService<IAstronomyCrossDomainValidationRuleRegistry>());Assert.NotNull(p.GetRequiredService<IAstronomyKnowledgeGraphValidationRuleRegistry>());}}
